use crate::ecs::{Ecs, EcsError};
use crate::{doc_lines_filter, snake_case_filter};
use minijinja::value::{Serde, Value};
use minijinja::{Environment, context};
use std::fs::File;
use std::io::{BufReader, Write};
use std::{env, io};

/// Allows emitted as an outer attribute on every generated top-level item.
///
/// The generated files are pulled in with `include!`, which rejects inner attributes, so the
/// allows can't go at the top of each file. Attaching them per item keeps them from leaking into
/// the user's surrounding module. They cover lints that aren't actionable for users: the
/// `unsafe` accessors exist even with `allow_unsafe: false`, and the opt-in clippy groups flag
/// style choices of the templates. Default-level clippy lints stay active, so the compile fixture
/// keeps the templates themselves honest.
const LINT_ALLOWS: &str = "#[allow(unsafe_code, unused_qualifications, elided_lifetimes_in_paths, missing_docs, clippy::pedantic, clippy::nursery, clippy::restriction)]";

/// Joins the generated files into the single file `sillyecs::include_ecs!` wraps in a module.
///
/// If any user type is referred to by its bare name (no `paths` entry), the module glob-imports
/// its parent, where the include site has to bring those types into scope.
fn module_code(uses_bare_names: bool, files: [&str; 4]) -> String {
    let mut module =
        String::from("// Generated by sillyecs-build. Include with `sillyecs::include_ecs!`.\n\n");
    if uses_bare_names {
        module.push_str(
            "// Some user types have no `paths` entry and are referred to by their bare names.\n\
             #[allow(unused_imports, clippy::wildcard_imports)]\n\
             use super::*;\n\n",
        );
    }
    for file in files {
        module.push_str(file);
        module.push('\n');
    }
    module
}

#[derive(Default)]
pub struct EcsCode {
    pub components: String,
    pub archetypes: String,
    pub systems: String,
    pub world: String,
    /// All generated code in one file, for `sillyecs::include_ecs!`.
    pub module: String,
}

#[derive(thiserror::Error, Debug)]
pub enum WriteCodeError {
    #[error("Could not access directory {0}: {1}")]
    InvalidDirectory(String, io::Error),
    #[error("Failed to open file {0}: {1}")]
    FailedToOpenFile(String, io::Error),
    #[error("Failed to write to file {0}: {1}")]
    FailedToWriteFile(String, io::Error),
}

impl EcsCode {
    pub fn generate<R>(reader: BufReader<R>) -> Result<EcsCode, EcsError>
    where
        R: io::Read,
    {
        let mut ecs: Ecs = serde_yaml::from_reader(reader)?;
        ecs.ensure_state_consistency()?;
        ecs.ensure_component_consistency()?;
        ecs.ensure_distinct_archetype_components()?;
        ecs.ensure_system_consistency()?;
        ecs.ensure_view_consistency()?;
        ecs.ensure_world_consistency()?;
        ecs.finish()?;
        let uses_bare_names = [&ecs.paths.components, &ecs.paths.states, &ecs.paths.systems]
            .iter()
            .any(|prefix| prefix.is_empty());

        let mut env = Environment::new();
        env.add_filter("snake_case", snake_case_filter);
        env.add_filter("doc_lines", doc_lines_filter);
        env.add_global("lint_allows", LINT_ALLOWS);

        env.add_template("world", include_str!("../templates/world.rs.jinja2"))?;
        env.add_template(
            "components",
            include_str!("../templates/components.rs.jinja2"),
        )?;
        env.add_template(
            "archetypes",
            include_str!("../templates/archetypes.rs.jinja2"),
        )?;
        env.add_template("systems", include_str!("../templates/systems.rs.jinja2"))?;

        // Serialize the ECS once; `Value` clones share the same data.
        let ecs = Value::from(Serde(&ecs));

        let world_code = env.get_template("world")?.render(context! {
            ecs => ecs.clone(),
        })?;

        let component_code = env.get_template("components")?.render(context! {
            ecs => ecs.clone(),
        })?;

        let archetype_code = env.get_template("archetypes")?.render(context! {
            ecs => ecs.clone(),
        })?;

        let system_code = env.get_template("systems")?.render(context! {
            ecs => ecs.clone(),
        })?;

        let module = module_code(
            uses_bare_names,
            [&component_code, &archetype_code, &system_code, &world_code],
        );

        Ok(EcsCode {
            components: component_code,
            archetypes: archetype_code,
            world: world_code,
            systems: system_code,
            module,
        })
    }

    /// Writes generated code to multiple files in the output directory specified
    /// by the `OUT_DIR` environment variable.
    ///
    /// # Returns
    /// - `Ok(())` if all files are written successfully.
    /// - `Err(WriteCodeError)` if the `OUT_DIR` environment variable is not set
    ///   or is not a valid directory, or if there is an error opening or writing
    ///   to any file.
    ///
    /// # Errors
    /// This function returns a `WriteCodeError` in the following cases:
    /// - If the `OUT_DIR` environment variable is not set or points to an invalid directory.
    /// - If a file cannot be created in the specified directory.
    /// - If a file fails to write the content.
    pub fn write_files(&self) -> Result<(), WriteCodeError> {
        let out_dir = env::var("OUT_DIR").map_err(|_| {
            WriteCodeError::InvalidDirectory(
                String::from("(OUT_DIR)"),
                io::Error::new(
                    io::ErrorKind::NotADirectory,
                    "The specified path is not a directory",
                ),
            )
        })?;
        self.write_files_to(out_dir)
    }

    /// Writes generated code to multiple files in the specified output directory.
    ///
    /// # Parameters
    /// - `out_dir`: The output directory path where the files will be written.
    ///
    /// # Returns
    /// - `Ok(())` if all files are written successfully.
    /// - `Err(WriteCodeError)` if there is an error opening or writing to any file.
    ///
    /// # Files Written
    /// - `ecs_gen.rs`: All of the below in one file, for `sillyecs::include_ecs!`.
    /// - `components_gen.rs`: Contains the generated code for components.
    /// - `archetypes_gen.rs`: Contains the generated code for archetypes.
    /// - `systems_gen.rs`: Contains the generated code for systems.
    /// - `world_gen.rs`: Contains the generated code for the world.
    ///
    /// # Errors
    /// This function returns a `WriteCodeError` in the following cases:
    /// - If a file cannot be created in the specified directory.
    /// - If a file fails to write the content.
    pub fn write_files_to<P>(&self, out_dir: P) -> Result<(), WriteCodeError>
    where
        P: AsRef<str>,
    {
        let out_dir = out_dir.as_ref();

        if !std::path::Path::new(out_dir).is_dir() {
            return Err(WriteCodeError::InvalidDirectory(
                out_dir.to_string(),
                io::Error::new(
                    io::ErrorKind::NotADirectory,
                    "The specified path is not a directory",
                ),
            ));
        }

        Self::write_file(out_dir, "components_gen.rs", &self.components)?;
        Self::write_file(out_dir, "archetypes_gen.rs", &self.archetypes)?;
        Self::write_file(out_dir, "systems_gen.rs", &self.systems)?;
        Self::write_file(out_dir, "world_gen.rs", &self.world)?;
        Self::write_file(out_dir, "ecs_gen.rs", &self.module)?;
        Ok(())
    }

    fn write_file(out_dir: &str, file_name: &str, content: &str) -> Result<(), WriteCodeError> {
        let path = format!("{out_dir}/{file_name}");
        let mut file =
            File::create(path).map_err(|e| WriteCodeError::FailedToOpenFile(e.to_string(), e))?;
        file.write_all(content.as_bytes())
            .map_err(|e| WriteCodeError::FailedToWriteFile(e.to_string(), e))?;
        Ok(())
    }
}
